import { useEffect, useRef } from "react";

/**
 * Sweeping ECG trace (like a bedside monitor): the strip generated by the Python simulator
 * is drawn at real-time speed, erasing ahead of the cursor, and loops until new data arrives.
 */
export function EcgCanvas({
  samples,
  sampleRate = 125,
  height = 72,
  color = "#059669",
  disconnected = false,
}: {
  samples: number[] | undefined;
  sampleRate?: number;
  height?: number;
  color?: string;
  disconnected?: boolean;
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const data = useRef<number[]>([]);
  data.current = samples && samples.length > 10 ? samples : [];

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    let raf = 0;
    let w = 0;
    let h = 0;
    let lastIdx = 0;
    const start = performance.now();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      w = Math.max(50, rect.width);
      h = height;
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      drawGrid();
    };
    const drawGrid = () => {
      ctx.strokeStyle = "rgba(11,31,68,0.05)";
      ctx.lineWidth = 1;
      for (let x = 0; x < w; x += 16) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }
    };
    const y = (v: number) => h * 0.62 - v * h * 0.42;

    let lastNow = 0;
    const frame = (now: number) => {
      const s = data.current;
      const n = s.length || 500;
      const idx = Math.floor(((now - start) / 1000) * sampleRate) % n;
      const px = (i: number) => (i / n) * w;
      if (lastNow && now - lastNow > 500 && s.length) {
        // resumed after a pause (background tab): repaint the whole strip with a gap at the cursor
        ctx.clearRect(0, 0, w, h);
        ctx.strokeStyle = disconnected ? "#94a3b8" : color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        for (let i = 0; i < n; i++) {
          if (i > idx && i < idx + 6) continue;
          if (i === 0 || i === idx + 6) ctx.moveTo(px(i), y(s[i]));
          else ctx.lineTo(px(i), y(s[i]));
        }
        ctx.stroke();
        lastIdx = idx;
      }
      lastNow = now;
      const from = lastIdx;
      const to = idx >= from ? idx : n; // wrap
      // erase band ahead of cursor
      ctx.clearRect(px(from), 0, px(Math.min(to + 6, n)) - px(from) + 2, h);
      ctx.strokeStyle = disconnected || !s.length ? "#94a3b8" : color;
      ctx.lineWidth = 2;
      ctx.lineJoin = "round";
      ctx.beginPath();
      for (let i = Math.max(0, from - 1); i <= Math.min(to, n - 1); i++) {
        const v = s.length ? s[i] : 0;
        if (i === Math.max(0, from - 1)) ctx.moveTo(px(i), y(v));
        else ctx.lineTo(px(i), y(v));
      }
      ctx.stroke();
      lastIdx = idx >= from ? idx : 0;
      raf = requestAnimationFrame(frame);
    };

    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(canvas);
    raf = requestAnimationFrame(frame);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
    };
  }, [sampleRate, height, color, disconnected]);

  return (
    <div className="relative">
      <canvas ref={ref} style={{ width: "100%", height }} aria-label="ECG trace, lead II" role="img" />
      {(disconnected || !samples?.length) && (
        <span className="absolute inset-0 flex items-center justify-center text-xs font-bold tracking-widest text-slate-400">
          {disconnected ? "NO SIGNAL" : "WAITING FOR DATA"}
        </span>
      )}
    </div>
  );
}
